void ArgumentsPatch::parse()
{
	_parser.process(*qApp);

	if (_parser.positionalArguments().size() > 3) {
		qWarning() << qPrintable(
		    QCoreApplication::translate("Arguments", "Error: too much parameters"));
		exit(1);
	}

	QStringList paths = wilcardParse();
	if (!paths.isEmpty()) {
		_path = paths.first();
		if (paths.size() > 1) {
			_target_file = paths.at(1);
		}
	}
	mapNamesFromFiles();
}

