void FF7Font::openTxt(const QString &data)
{
	int tableCount = _windowBinFile->tableCount();
	QStringList lines = data.split(QRegularExpression("\\s*(\\r\\n|\\r|\\n)\\s*"), Qt::SkipEmptyParts);
	QRegularExpression nameRegExp("#NAME\\s+(\\S.*)"), letterRegExp("\\s*\"([^\"]*|\\\"*)\"\\s*,?\\s*");
	// nameRegExp:		#NAME blah blah blah
	// letterRegExp:	"Foo", "Foo","Foo"
	QStringList table;

	if (tableCount < 1) {
		qWarning() << "invalid windowBinFile!";
		return;
	}

	for (const QString &line : std::as_const(lines)) {
		if (line.startsWith("#")) {
			QRegularExpressionMatch match = nameRegExp.match(line);
			if (match.hasMatch()) {
				_name = match.captured(1).trimmed();
			}
		}
		else {
			QRegularExpressionMatchIterator it = letterRegExp.globalMatch(line);
			while (it.hasNext() ) {
				table.append(it.next().captured(1));

				if (table.size() == 224) {
					_tables.append(table);
					if (_tables.size() > tableCount) {
						return;
					}
					table = QStringList();
				}
			}
		}
	}

	if (!table.isEmpty()) {
		table.resize(224);

		_tables.append(table);
	}

	//print();
}

QString FF7Font::saveTxt()
{
	QString data;

	if (!_name.isEmpty()) {
		data.append("#NAME\t").append(_name).append("\n");

//print();
}

QString FF7Font::saveTxt()
{
	QString data;

	if (!_name.isEmpty()) {
		data.append("#NAME\t").append(_name).append("\n");
	}

	for (const QStringList &t : std::as_const(_tables)) {
		for (int j=0; j<14; ++j) {
			for (int i=0; i<16; ++i) {
				data.append(QString("\"%1\"").arg(t[j*16 + i]));
				if (i<15) {
					data.append(",");
				}
			}
			if (j<13) {
				data.append(",");
			}
			data.append("\n");
		}
		data.append("\n");
	}

	return data;
}

