			return false;
		}

		if (bool(exists)) {
			quint16 isBigTile, depth;

			if (device()->read((char *)&isBigTile, 2) != 2 ||
					device()->read((char *)&depth, 2) != 2) {
				qWarning() << "BackgroundTexturesIOPC::read cannot read isBigTile or depth" << texID;
				return false;
