void Script::swapGroupIds(quint8 groupId1, quint8 groupId2)
{
	for (Opcode &opcode : _opcodes) {
		qint16 groupID = opcode.groupID();
		if (groupID == groupId1) {
			opcode.setGroupID(groupId2);
		} else if (groupID == groupId2) {
