bool Script::removeTexts()
{
	bool modified = false;
	qsizetype i = 0;
	for (const Opcode &opcode : std::as_const(_opcodes)) {
		if (opcode.id() != OpcodeKey::ASK
				&& opcode.id() != OpcodeKey::MPNAM
				&& opcode.textID() != -1) {
			_opcodes.removeAt(i);
			modified = true;
		}
		i += 1;
	}

	return modified;
}

