	}

	return true;
}

qint8 FieldPS::saveModels(const QString &path, bool compress)
{
	QByteArray newData;

	if (saveModels(newData, compress)) {
		QFile fic(path);
		if (!fic.open(QIODevice::WriteOnly | QIODevice::Truncate)) {
			return 2;
		}
		fic.write(newData);
		fic.close();

		return 0;
	}

	return 1;
}

