bool FieldPS::exportToChunks(const QDir &dir, FieldSections parts)
{
	QList<FieldSection> sections = orderOfSections();
	for (FieldSection section : sections) {
		if (!parts.testFlag(section)) {
			continue;
		}
		QString extension;
		switch (section) {
		case Scripts:
			extension = "chunk.1";
			break;
		case Camera:
			extension = "chunk.2";
			break;
		case ModelLoader:
			extension = "chunkps.3";
			break;
		case Walkmesh:
			extension = "chunk.5";
			break;
		case Background:
			extension = "chunk.6";
			break;
		case Encounter:
			extension = "chunk.7";
			break;
		case Inf:
			extension = "chunk.8";
			break;
		default:
			return false;
		}

		QFile f(dir.filePath(QString("%1.%2").arg(name(), extension)));
		if (!f.open(QIODevice::WriteOnly | QIODevice::Truncate)) {
			return false;
		}
		bool ok = false;
		f.write(saveSection(section, ok));
		f.close();
	}

	FieldPC fieldPC(*this);
	BackgroundFilePS *bg = static_cast<BackgroundFilePS *>(background(false));
	BackgroundFilePC bgPc = bg->toPC(&fieldPC);

	QFile f(dir.filePath(QString("%1.chunk.9").arg(name())));

bool ok = false;
		f.write(saveSection(section, ok));
		f.close();
	}

	FieldPC fieldPC(*this);
	BackgroundFilePS *bg = static_cast<BackgroundFilePS *>(background(false));
	BackgroundFilePC bgPc = bg->toPC(&fieldPC);

	QFile f(dir.filePath(QString("%1.chunk.9").arg(name())));
	if (!f.open(QIODevice::WriteOnly | QIODevice::Truncate)) {
		return false;
	}
	f.write(bgPc.save());
	f.close();

	QFile fPal(dir.filePath(QString("%1.chunk.4").arg(name())));
	if (!fPal.open(QIODevice::WriteOnly | QIODevice::Truncate)) {
		return false;
	}
	fPal.write(bgPc.savePal());
	fPal.close();

	return true;
}

