	// Texture coordinates
	quint32 offsetToTexCoords = offsetToVertex + partHeader.offsetTexcoord;

	if (!device()->seek(offsetToTexCoords)) {
		qWarning() << "BsxFile::readPart error 3";
		return false;
	}

