				if (maxSize > 1) {
					qsizetype id = effectLayers->size();
					for (const QList<quint16> &tileIDs: dst) {
						if (tileIDs.size() > 1) {
							for (qsizetype i = 0; i < tileIDs.size(); ++i) {
								if (id + i >= effectLayers->size()) {
									effectLayers->append(QList<quint16>());
