bool FieldPC::importModelLoader(const QByteArray &sectionData, bool isPSField, QIODevice *bsxDevice)
{
	FieldModelLoaderPC *modelLoader = fieldModelLoader(false);

	if (isPSField) {
		FieldModelLoaderPS modelLoaderPS(this);
		if (!modelLoaderPS.open(sectionData)) {
			return false;
		}
		if (!bsxDevice->open(QIODevice::ReadOnly)) {
			return false;
		}

		QByteArray decompressedBsx = LZS::decompressAllWithHeader(bsxDevice->readAll());
		QBuffer bsxDeviceDec;
		bsxDeviceDec.setData(decompressedBsx);
		bsxDeviceDec.open(QIODevice::ReadOnly);

		BsxFile bsx(&bsxDeviceDec);
		bool ok;
		*modelLoader = modelLoaderPS.toPC(&bsx, CharArchive::instance(), &ok);

QByteArray decompressedBsx = LZS::decompressAllWithHeader(bsxDevice->readAll());
		QBuffer bsxDeviceDec;
		bsxDeviceDec.setData(decompressedBsx);
		bsxDeviceDec.open(QIODevice::ReadOnly);

		BsxFile bsx(&bsxDeviceDec);
		bool ok;
		*modelLoader = modelLoaderPS.toPC(&bsx, CharArchive::instance(), &ok);

		if (!ok) {
			return false;
		}
	} else {
		FieldModelLoaderPC *modelLoader = fieldModelLoader(false);
		if (!modelLoader->open(sectionData)) {
			return false;
		}
	}

	modelLoader->setModified(true);
	modelLoader->setOpen(true);

	return true;
}

bool FieldPC::exportToChunks(const QDir &dir, FieldSections parts)
{
	quint8 sectionNum = 1;
	QList<FieldSection> sections = orderOfSections();
	for (FieldSection section : sections) {
		if (!parts.testFlag(section)) {
			++sectionNum;
			continue;
		}
		QFile f(dir.filePath(QString("%1.chunk.%2").arg(name()).arg(sectionNum)));
		if (!f.open(QIODevice::WriteOnly | QIODevice::Truncate)) {
			setErrorString(QString("%1: %2").arg(f.fileName(), f.errorString()));
			return false;
		}
		bool ok = false;
		f.write(saveSection(section, ok));
		f.close();
		++sectionNum;
	}

	return true;
}

