	// Fill with zeroes
	data = InfData();
	QByteArray name = field()->name().toLatin1().leftJustified(8, '\0', true);

	memcpy(data.name, name.constData(), 8);
	data.control = 128; // Left on the left
	data.camera_range.left = -256;
