		size += std::min(_opcode.opcodeUnused1C.subSize, quint8(128));
	} else if (id() == OpcodeKey::KAWAI) {
		size = std::max(_opcode.opcodeKAWAI.opcodeSize, quint8(1));
	}

	return size;
}

QByteArray Opcode::toByteArray() const
{
	quint8 s = size();
	QByteArray ret;

	if (s > 0) {
		ret.reserve(s);
		ret.append(char(id()));
		ret.append(params());
	}

	return ret;
}

QByteArray Opcode::serialize() const
{
	QByteArray data = resizableData();
	QByteArray ret;
	ret.reserve(qsizetype(sizeof(_opcode)) + data.size());
	return ret
	        .append(reinterpret_cast<const char *>(&_opcode), sizeof(_opcode))
	        .append(resizableData());
}

Opcode Opcode::unserialize(const QByteArray &data)
{
	Opcode ret;
	memset(&ret._opcode, 0, sizeof(ret._opcode));
	memcpy(&ret._opcode, data.constData(), std::min(sizeof(ret._opcode), size_t(data.size())));
	ret.clearResizableDataPointers();
	ret.setResizableData(data.mid(sizeof(ret._opcode)));

	return ret;
}

