	if (posAKAO < quint32(posTexts) && posTexts + 4 < dataSize) {
		posAfterScriptsAndroid = data.lastIndexOf(QByteArrayView(constData + posTexts, 4), posAKAO);
	}

	for (quint8 i = 0; i < nbScripts; ++i) {
