int Field::sectionSize(FieldSection part) const
{
	int idPart = sectionId(part);

	if (idPart < sectionCount() - 1) {
		return int(sectionPosition(idPart + 1)) - paddingBetweenSections() - int(sectionPosition(idPart));
	}
	return -1;
}

