QHash<void *, QImage> FieldModelFilePC::loadedTextures()
{
	QHash<void *, QImage> ret;
	QHashIterator<quint64, QImage> it(_loadedTex);

	while (it.hasNext()) {
		it.next();
		ret.insert(reinterpret_cast<void *>(it.key()), it.value());
	}

	return ret;
