int FieldArchive::appendField(Field *field)
{
	qsizetype mapId = _mapList.mapNames().indexOf(field->name());
	if (mapId < 0) {
		if (_mapList.mapNames().isEmpty()) {
			mapId = Data::maplist(field->isPC()).indexOf(field->name());
