					scale = fieldModelPS->scale();
					// colors = fieldModelPS->lightColors();
					boneCount -= 1;
					if (boneCount <= 0) {
						boneCount = 1;
					}
				}
				deb.write(QString("%1 > model %2: bones %3\nscale %4\nunknown %5\n")
						  .arg(name)
						  .arg(modelId)
						  .arg(boneCount)
						  .arg(scale)
						  .arg(modelLoader->unknown(modelId))
