bool FieldArchive::find(bool (*predicate)(Field *, SearchQuery *, SearchIn *),
						SearchQuery *toSearch, int &mapID, SearchIn *searchIn,
						Sorting sorting, SearchScope scope)
{
	Q_UNUSED(sorting)
	FieldArchiveIterator it(*this);
	if (!it.seek(mapID)) {
		return false;
	}

	while (it.hasNext()) {
		Field *f = it.next();
		mapID = it.mapId();
		if (f != nullptr && (*predicate)(f, toSearch, searchIn)) {
			return true;
		}
		searchIn->reset();
		if (scope >= FieldScope) {
			break;
		}
	}
	return false;
}

bool FieldArchive::findLast(bool (*predicate)(Field *, SearchQuery *, SearchIn *),
						SearchQuery *toSearch, int &mapID, SearchIn *searchIn,
						Sorting sorting, SearchScope scope)
{
	Q_UNUSED(sorting)
	FieldArchiveIterator it(*this);
	if (!it.seek(mapID)) {
		return false;
	}

	while (it.hasPrevious()) {
		Field *f = it.previous();
		mapID = it.key();
		if (f != nullptr && (*predicate)(f, toSearch, searchIn)) {
			return true;
		}
		searchIn->toEnd();
		if (scope >= FieldScope) {
			break;
		}
	}

	return false;
}

