void FontGrid::mousePressEvent(QMouseEvent *e)
{
	int letter = getLetter(e->pos());
	if (letter < _letterCountH*_letterCountV) {
		setLetter(quint8(letter));
		emit letterClicked(letter);
	}
	setFocus();
}

