	bool enabled = !modelIndexList.isEmpty() &&
	               item &&
	               !item->isDirectory();

	renameButton->setEnabled(enabled);
	replaceButton->setEnabled(enabled);
	extractButton->setEnabled(enabled);
	removeButton->setEnabled(enabled);
}

