void VarManager::setFieldArchive(FieldArchive *fieldArchive)
{
	this->fieldArchive = fieldArchive;
	searchScope->setEnabled(fieldArchive != nullptr);

	if (!fieldArchive) {
		currentField = nullptr;
		clearUsageResults();
		return;
	}

	if (isVisible()) {
		search();
	}
}

void VarManager::setCurrentField(Field *field)
{
	if (currentField == field) {
		return;
	}

	currentField = field;

	// Field-list navigation only refreshes usage results in Local used mode.
	if (searchScope->currentData().toInt() != LocalUsedScope) {
		return;
	}

	if (!currentField) {
		clearUsageResults();
		return;
	}

	// During archive replacement, the field can be selected before
	// setFieldArchive() receives the new archive. Avoid scanning until then.
	if (isVisible() && fieldArchive) {
		search();

if (!currentField) {
		clearUsageResults();
		return;
	}

	// During archive replacement, the field can be selected before
	// setFieldArchive() receives the new archive. Avoid scanning until then.
	if (isVisible() && fieldArchive) {
		search();
	} else {
		clearUsageResults();
	}
}

QPair<quint8, quint8> VarManager::banksFromRow(int row)
{
	switch (row) {
	case 0:
		return qMakePair(quint8(1), quint8(2));
	case 1:
		return qMakePair(quint8(3), quint8(4));
	case 2:
		return qMakePair(quint8(5), quint8(6));
	case 3:
		return qMakePair(quint8(11), quint8(12));
	case 4:
		return qMakePair(quint8(13), quint8(14));
	case 5:
		return qMakePair(quint8(15), quint8(7));
	}
	Q_ASSERT(false);
	return qMakePair(quint8(0), quint8(0));
}

