		filter.append(txtF = tr("Translation file %1 (*.txt)").arg(MAKOU_REACTOR_NAME));
	}
	QString selectedFilter;

	QString path = QFileDialog::getSaveFileName(this, tr("Export font"), "window", filter.join(";;"), &selectedFilter);
	if (path.isNull()) {
		return;
	}

