int QColorLuminancePicker::y2val(int y)
{
	int d = height() - 2 * coff - 1;

	return 255 - (y - coff) * 255 / d;
}

int QColorLuminancePicker::val2y(int v)
{
	int d = height() - 2 * coff - 1;

	return coff + (255 - v) * d / 255;
}

