	int x, y;
	uint *pixel = (uint *) img.scanLine(0);

	for (y = 0; y < h; y++) {
		const uint *end = pixel + w;
		x = 0;
		while (pixel < end) {
			QPoint p(x, y);
			QColor c;
			c.setHsv(huePt(p), satPt(p), 200);
			*pixel = PsColor::fromPsColor(PsColor::toPsColor(c.rgb()));
			++pixel;
			++x;
		}
	}

x = 0;
		while (pixel < end) {
			QPoint p(x, y);
			QColor c;
			c.setHsv(huePt(p), satPt(p), 200);
			*pixel = PsColor::fromPsColor(PsColor::toPsColor(c.rgb()));
			++pixel;
			++x;
		}
	}

	pix = QPixmap::fromImage(img);
}

