			for (const Arrow &arrow : infFile->arrows()) {
				if (arrow.type != 0) {
					arrowList->addItem(tr("Arrow %1").arg(arrowID));
				} else {
					QListWidgetItem *item = new QListWidgetItem(tr("Unused"));
					item->setForeground(Data::color(Data::ColorDisabledForeground));
