		rangeEdit[2]->setValue(range1.right);
		rangeEdit[3]->setValue(range1.left);

		bgFlagEdit[0]->setValue(infFile->bgLayer1Flag());
		bgFlagEdit[1]->setValue(infFile->bgLayer2Flag());
