		Range old = infFile->cameraRange();
		qint16 oldv = 0;

		switch (id) {
		case 0:
			oldv = old.top;
			break;
		case 1:
			oldv = old.bottom;
			break;
		case 2:
			oldv = old.right;
			break;
		case 3:
			oldv = old.left;
			break;
		}

		if (oldv != v) {
			switch (id) {
			case 0:
