				break;
			case 1:
				old.bottom = qint16(v);
				break;
			case 2:
				old.right = qint16(v);
				break;
			case 3:
				old.left = qint16(v);
				break;
			}
			infFile->setCameraRange(old);

			emit modified();
		}
	}
}


