int ScriptEditorGenericList::paramSize(int type)
{
	switch (type) {
	case dword:
		return 32;
	case color:
		return 24;
	case word:
	case sword:
	case jump_l:
	case coord_x:
	case coord_y:
	case coord_z:
	case window_w:
	case window_h:
	case item_id:
	case vitesse2:
	case polygone_id:
	case sound_id:
	case keys:
	case label:
	case field_id:
		return 16;
	case script_id:
		return 5;
	case bank:
		return 4;
	case priorite:
		return 3;
	case bit:
		return 1;
	}
	return 8;
}

