void ScriptEditorBinaryOpPage::changeCurrentOpcode(int index)
{
	OpcodeKey key;

	type1->setEnabled(true);
	type2->setEnabled(true);
	helpWidget->hide();

	switch (index) {
	case 0:
		key = type1->isChecked()
				? OpcodeKey::SETBYTE
				: OpcodeKey::SETWORD;
		break;
	case 1:
		key = type1->isChecked()
				? OpcodeKey::PLUS
				: OpcodeKey::PLUS2;
		break;
	case 2:
		key = type1->isChecked()
				? OpcodeKey::PLUSX
				: OpcodeKey::PLUS2X;
		break;
	case 3:
		key = type1->isChecked()
				? OpcodeKey::MINUS
				: OpcodeKey::MINUS2;
		break;
	case 4:
		key = type1->isChecked()

? OpcodeKey::PLUSX
				: OpcodeKey::PLUS2X;
		break;
	case 3:
		key = type1->isChecked()
				? OpcodeKey::MINUS
				: OpcodeKey::MINUS2;
		break;
	case 4:
		key = type1->isChecked()
				? OpcodeKey::MINUSX
				: OpcodeKey::MINUS2X;
		break;
	case 5:
		key = type1->isChecked()
				? OpcodeKey::MUL
				: OpcodeKey::MUL2;
		break;
	case 6:
		key = type1->isChecked()
				? OpcodeKey::DIV
				: OpcodeKey::DIV2;
		helpWidget->show();
		break;
	case 7:
		key = type1->isChecked()
				? OpcodeKey::MOD
				: OpcodeKey::MOD2;
		helpWidget->show();
		break;
	case 8:
		key = type1->isChecked()
				? OpcodeKey::AND
				: OpcodeKey::AND2;
		break;
	case 9:
		key = type1->isChecked()
				? OpcodeKey::OR
				: OpcodeKey::OR2;
		break;
	case 10:
		key = type1->isChecked()
				? OpcodeKey::XOR
				: OpcodeKey::XOR2;
		break;
	case 11:
		key = OpcodeKey::LBYTE;
		type1->setEnabled(false);
		type2->setEnabled(false);
		type1->blockSignals(true);
		type2->blockSignals(true);
		type1->setChecked(true);
		type2->setChecked(false);
		type1->blockSignals(false);
		type2->blockSignals(false);
		break;
	case 12:
		key = OpcodeKey::HBYTE;
		type1->setEnabled(false);
		type2->setEnabled(false);

type2->blockSignals(true);
		type1->setChecked(true);
		type2->setChecked(false);
		type1->blockSignals(false);
		type2->blockSignals(false);
		break;
	case 12:
		key = OpcodeKey::HBYTE;
		type1->setEnabled(false);
		type2->setEnabled(false);
		type1->blockSignals(true);
		type2->blockSignals(true);
		type1->setChecked(false);
		type2->setChecked(true);
		type1->blockSignals(false);
		type2->blockSignals(false);
		break;
	default:
		key = opcode().id();
		break;
	}

	if (key != opcode().id()) {
		opcode().op().id = key;

		emit opcodeChanged();
	}
}

