int WindowBinFile::absoluteId(quint8 table, quint8 id)
{
    if (id >= tableSize(table)) {
        return -1;
    }

    int absId = id;
    for (int i=0; i<table; ++i) {
        absId += tableSize(i);
    }
    return absId;
}

