            img.setPixel(x*4+3, y*4+2, Qt::black);
            img.setPixel(x*4+3, y*4+3, Qt::black);

            if (x==15) {
                x = 0;
                ++y;
            } else {
                ++x;
            }
        }
    }

    img.save("palettes.png");
}

