bool IsoArchiveFF7::isDisc(int num) const
{
    QIODevice *file = fileDevice("MINT/DISKINFO.CNF");
    if (!file) {
        return false;
    }

    if (!file->isOpen() && !file->open(QIODevice::ReadOnly)) {
        return false;
    }
    file->reset();

    QByteArray l = file->readLine(16);
    // Trim \0 at the end
    QString line = QString::fromLatin1(l, qstrnlen(l, 16));
    return line.startsWith(QString("DISK000%1").arg(num));
}

