{
    if (_lgp->seek(_header->filePosition() + 24 + pos())) {
        qint64 size = this->size();
        if (size < 0) {
            return -1;
        }
        return _lgp->read(data, qMin(maxSize, size - pos()));
    }
    return -1;
}

