/*!
 * Returns a list of file paths sorted by file position.
 */
QStringList Lgp::fileList() const
{
    QStringList ret;

    if (_files->isEmpty()) {
        return ret;

/*!
 * Returns a list of file paths sorted by file position.
 */
QStringList Lgp::fileList() const
{
    QStringList ret;

    if (_files->isEmpty()) {
        return ret;
    }

    QList<const LgpHeaderEntry *> entries = _files->filesSortedByPosition();
    for (const LgpHeaderEntry *entry : std::as_const(entries)) {
        ret.append(entry->filePath());
    }

    return ret;
}

/*!
 * Returns the number of files in the archive, or -1 if there is an error.
 */
int Lgp::fileCount() const
{
    return _files->size();
}

