        return false;
    }

    LgpToc newToc;

    // Write files
    QList<const LgpHeaderEntry *> filesSortedByPosition = _files->filesSortedByPosition();
    for (const LgpHeaderEntry *lgpEntry : std::as_const(filesSortedByPosition)) {
        // Cancels if requested
        if (observer && observer->observerWasCanceled()) {
            temp.remove();
            setError(AbortError);
            return false;
        }

        // Infos for the current file
        const QString &path = lgpEntry->filePath();

        // Notify the progression
        if (observer) {
            observer->setObserverValue(fileId++);
        }

        // Changes the header info
        LgpHeaderEntry *newEntry = new LgpHeaderEntry(*lgpEntry);
        newEntry->setFilePosition(quint32(temp.pos()));
        newEntry->setFile(nullptr);
        newEntry->setModifiedFile(nullptr);
        newToc.addEntry(newEntry);

        // Writes the file
        QIODevice *io = modifiedFile(path);
        if (io == nullptr) {
            temp.remove();
            setError(FileNotFoundError, QT_TRANSLATE_NOOP(Lgp, QStringLiteral("File '%1' not found")
                                                          .arg(path)));
            return false;
        }
        if (!io->open(QIODevice::ReadOnly)) {
            temp.remove();
            setError(OpenError, io->errorString());
            return false;
        }
        // File: writes the name

setError(FileNotFoundError, QT_TRANSLATE_NOOP(Lgp, QStringLiteral("File '%1' not found")
                                                          .arg(path)));
            return false;
        }
        if (!io->open(QIODevice::ReadOnly)) {
            temp.remove();
            setError(OpenError, io->errorString());
            return false;
        }
        // File: writes the name
        if (temp.write(lgpEntry->fileName().toLatin1().leftJustified(20, '\0', true)) != 20) {
            temp.remove();
            setError(WriteError, temp.errorString());
            return false;
        }
        // File: writes the size
        bool ok;
        const QByteArray data = readAll(io, &ok);
        if (!ok) {
            setError(ReadError, io->errorString());
            return false;
        }
        io->close();
        const qint64 size = data.size();
        if (temp.write(reinterpret_cast<const char *>(&size), 4) != 4) {
            temp.remove();
            setError(WriteError, temp.errorString());
            return false;
        }
        // File: writes data
        if (temp.write(data) != size) {
            temp.remove();
            setError(WriteError, temp.errorString());
            return false;
        }
    }

    // Writes the product name (FINAL FANTASY7)
    if (temp.write(productName().toLatin1().leftJustified(LGP_PRODUCT_NAME_SIZE, '\0', true)) != LGP_PRODUCT_NAME_SIZE) {
        temp.remove();
        setError(WriteError, temp.errorString());
        return false;
    }

    if (observer) {
        observer->setObserverValue(fileId);
    }

    // Go back to the header
    if (!temp.seek(16)) {
        temp.remove();
        setError(PositionError, temp.errorString());
        return false;
    }

    // Header: TOC
    QByteArray tocData;
    for (quint16 i = 0; i < LOOKUP_TABLE_ENTRIES; ++i) {
        QList<LgpHeaderEntry *> entries = newToc.entries(i);
        for (const LgpHeaderEntry *headerEntry : std::as_const(entries)) {

