IsoFileOrDirectory *IsoDirectory::fileOrDirectory(const QString &path) const
{
    qsizetype index = path.indexOf("/");

    if (index != -1) {
        IsoFileOrDirectory *fOrD = _filesAndDirectories.value(path.left(index).toUpper(), nullptr);

        if (fOrD == nullptr) {
            return nullptr;
        }

        if (fOrD->isDirectory()) {
            return static_cast<IsoDirectory *>(fOrD)->fileOrDirectory(path.mid(index + 1));

if (index != -1) {
        IsoFileOrDirectory *fOrD = _filesAndDirectories.value(path.left(index).toUpper(), nullptr);

        if (fOrD == nullptr) {
            return nullptr;
        }

        if (fOrD->isDirectory()) {
            return static_cast<IsoDirectory *>(fOrD)->fileOrDirectory(path.mid(index + 1));
        } else {
            return nullptr;
        }
    } else {
        return _filesAndDirectories.value(path.toUpper(), nullptr);
    }

}

