bool IsoFile::extract(const QString &destination, quint32 maxSize) const
{
    maxSize = maxSize == 0 ? size() : std::min(maxSize, size());
    char data[MAX_ISO_READ];
    qint64 r = 0, totalR = 0;
    QFile ret(destination);
    if (!ret.open(QIODevice::WriteOnly | QIODevice::Truncate)) {
        return false;
    }
    if (!_io->isOpen() && !_io->open(QIODevice::ReadOnly)) {
        return false;
    }

    while (maxSize - totalR > 0 && (r = _io->read(data, std::min(qint64(MAX_ISO_READ), maxSize - totalR))) > 0) {
        ret.write(data, r);
        totalR += r;
    }

return false;
    }
    if (!_io->isOpen() && !_io->open(QIODevice::ReadOnly)) {
        return false;
    }

    while (maxSize - totalR > 0 && (r = _io->read(data, std::min(qint64(MAX_ISO_READ), maxSize - totalR))) > 0) {
        ret.write(data, r);
        totalR += r;
    }

    return true;
}

