qint64 IsoArchiveIO::isoPos(qint64 pos)
{
    qint64 start = (pos % SECTOR_SIZE) - SECTOR_SIZE_HEADER;
    if (start < 0) {
        start = 0;
    } else if (start > SECTOR_SIZE_DATA) {
        start = SECTOR_SIZE_DATA;
    }

    return SECTOR_SIZE_DATA * (pos / SECTOR_SIZE) + start;
}

qint64 IsoArchiveIO::filePos(qint64 pos)
{
    return SECTOR_SIZE_HEADER + (pos / SECTOR_SIZE_DATA) * SECTOR_SIZE + pos % SECTOR_SIZE_DATA;
}

qint64 IsoArchiveIO::readIso(char *data, qint64 maxSize)
{
    qint64 read, readTotal = 0, seqLen;

    if (!seekIso(isoPos(pos()))) {
        return 0;
    }

    seqLen = std::min(SECTOR_SIZE_HEADER + SECTOR_SIZE_DATA - (pos() % SECTOR_SIZE), maxSize);
    if (seqLen < 0) {
        return 0;
    }

    while ((read = this->read(data, seqLen)) > 0) {
        data += read;
        maxSize -= read;
        readTotal += read;
        seqLen = std::min(qint64(SECTOR_SIZE_DATA), maxSize);
        // If we are at the end of the sector
        if (pos() % SECTOR_SIZE >= SECTOR_SIZE_HEADER + SECTOR_SIZE_DATA
                && !seek(pos() + SECTOR_SIZE_HEADER + SECTOR_SIZE_FOOTER)) {
            break;
        }

while ((read = this->read(data, seqLen)) > 0) {
        data += read;
        maxSize -= read;
        readTotal += read;
        seqLen = std::min(qint64(SECTOR_SIZE_DATA), maxSize);
        // If we are at the end of the sector
        if (pos() % SECTOR_SIZE >= SECTOR_SIZE_HEADER + SECTOR_SIZE_DATA
                && !seek(pos() + SECTOR_SIZE_HEADER + SECTOR_SIZE_FOOTER)) {
            break;
        }
    }

    return read < 0 ? read : readTotal;
}

QByteArray IsoArchiveIO::readIso(qint64 maxSize)
{
    char *data = new char[quint64(maxSize)];

    QByteArray baData(data, readIso(data, maxSize));

    delete[] data;

    return baData;
}

qint64 IsoArchiveIO::writeIso(const char *data, qint64 maxSize)
{
    qint64 write = 0, writeTotal = 0, seqLen;

    if (!seekIso(isoPos(pos()))) {
        return 0;
    }

    const qint64 startIsoPos = posIso();

    seqLen = std::min(SECTOR_SIZE_HEADER + SECTOR_SIZE_DATA - (pos() % SECTOR_SIZE), maxSize);

    while ((write = this->write(data, seqLen)) > 0) {
        data += write;
        maxSize -= write;
        writeTotal += write;
        seqLen = std::min(qint64(SECTOR_SIZE_DATA), maxSize);
        // If we are at the end of the sector
        if (pos() % SECTOR_SIZE >= SECTOR_SIZE_HEADER + SECTOR_SIZE_DATA
                && !seek(pos() + SECTOR_SIZE_HEADER + SECTOR_SIZE_FOOTER)) {
            break;
        }
    }

    if (writeTotal > 0) {
        const quint32 firstSector = quint32(startIsoPos / SECTOR_SIZE_DATA);
        const quint32 lastSector = quint32((startIsoPos + writeTotal - 1) / SECTOR_SIZE_DATA);

        for (quint32 sector = firstSector; sector <= lastSector; ++sector) {
            if (!ff7tk_psx_cd::repairSector(*this, sector)) {
                return -1;
            }
        }
    }

if (writeTotal > 0) {
        const quint32 firstSector = quint32(startIsoPos / SECTOR_SIZE_DATA);
        const quint32 lastSector = quint32((startIsoPos + writeTotal - 1) / SECTOR_SIZE_DATA);

        for (quint32 sector = firstSector; sector <= lastSector; ++sector) {
            if (!ff7tk_psx_cd::repairSector(*this, sector)) {
                return -1;
            }
        }
    }

    return write < 0 ? write : writeTotal;
}

