                isoFile->setPaddingAfter(quint8(fileWithPaddingAfter->paddingAfter() - isoFile->newSectorCount()));
                fileWithPaddingAfter->setPaddingAfter(0);
                if (isoFile->paddingAfter() > 0) {
                    filesWithPadding.replace(index, isoFile);
                } else {

