    case FF7SaveInfo::FORMAT::PS3: return;
    default: break;
    }

    if ((s < 0) || (s > 14) || (blockSize > 15))
        return;

    quint32 filesize = quint32(blockSize * FF7SaveInfo::fileSize(FF7SaveInfo::FORMAT::PSX));
