    Q_INVOKABLE static const QList<int> placeHolderIdList() {
        QList<int> phList;
        for (const MATERIA &m : get()->d->_materiaList) {
            if(m.name.startsWith(get()->d->_placeHolderFilter))
                phList.append(m.id);
