void CharEditor::calc_limit_value(QModelIndex item)
{
    int row = item.row();
    int limits = data.limits;
    if (list_limits->item(row)->checkState() == Qt::Checked)
        limits |= (1 << FF7Char::limitBitConvert(row));
    else
        limits &= ~(1 << FF7Char::limitBitConvert(row));
    setLimits(limits);
}

