bool ItemPreview::eventFilter(QObject *obj, QEvent *ev)
{
    if (obj != this->parent() && (obj != this)) {
        close();
        return true;
    }

    if (ev->type() == QEvent::MouseButtonPress || ev->type() == QEvent::Leave) {
        close();
        return true;
    }

    return event(ev);

}
