                case 4: element = FF7Item::elementEarth(id); effect.append(tr("Earth")); break;
                case 5: element = FF7Item::elementWind(id); effect.append(tr("Wind")); break;
                case 6: element = FF7Item::elementWater(id); effect.append(tr("Water")); break;
