    QString title = tr("Skills");
    if (_id != FF7Materia::EmptyId) {
        if (!FF7Materia::element(_id).isEmpty()) {
            title.append("-");
            title.append(FF7Materia::element(_id));
        }
        if (!FF7Materia::statString(_id).isEmpty()) {
