			.split('—')
			.slice(1)
			.join('—')
			.trim();
		const cleaned = after
			.replace(/\s*\(on [^)]+\)/gi, '')
			.replace(/\s+v[\d.]+$/i, '')
			.trim();
		core = cleaned || String(addon.name || addon.id || '');
	}
	return withAddonVersion(core, addon);
}

