/**
 * Detect FF7 PS1 disc number from a raw .bin (Mode 2 / 2352).
 * NTSC-U boots SCUS_941.63 / .64 / .65 for discs 1 / 2 / 3.
 */

const WINDOW = 4 * 1024 * 1024; // SYSTEM.CNF + early root sit near the start

const MARKERS = [
	{ disc: 1, needles: ['SCUS_941.63', 'SCUS-94163'] },
	{ disc: 2, needles: ['SCUS_941.64', 'SCUS-94164'] },
	{ disc: 3, needles: ['SCUS_941.65', 'SCUS-94165'] },
];

function indexOfBytes(haystack, needleBytes, start, end) {
	const limit = Math.min(end, haystack.length) - needleBytes.length;
	outer: for (let i = start; i <= limit; i++) {
		for (let j = 0; j < needleBytes.length; j++) {
			if (haystack[i + j] !== needleBytes[j]) continue outer;
		}
		return i;
	}
	return -1;
}

/**
 * @param {Uint8Array} bytes
 * @returns {{ disc: number, region: 'ntsc-u', marker: string } | null}
 */
export function detectFf7Disc(bytes) {
	if (!bytes || bytes.length < 0x10000) return null;

	const end = Math.min(bytes.length, WINDOW);
	const hits = [];

	for (const { disc, needles } of MARKERS) {
		for (const needle of needles) {
			const nb = new TextEncoder().encode(needle);
			const at = indexOfBytes(bytes, nb, 0, end);
			if (at >= 0) hits.push({ disc, marker: needle, at });
		}
	}

	if (!hits.length) return null;

	// Prefer the most specific / first hit; require a single disc number.
	const discs = [...new Set(hits.map((h) => h.disc))];
	if (discs.length !== 1) return null;

	hits.sort((a, b) => a.at - b.at);
	return { disc: discs[0], region: 'ntsc-u', marker: hits[0].marker };
}

/**
 * ic-layer-v1 — stackable disc-image byte patches.
 * Each record: { offset: number, hex: string } (hex = even-length hex string)
 */

export function parseHex(hex) {
	const clean = String(hex).replace(/\s+/g, '').toLowerCase();
	if (clean.length % 2 !== 0) {
		throw new Error('hex length must be even');
	}
	if (!/^[0-9a-f]*$/.test(clean)) {
		throw new Error('invalid hex');
	}
	const out = new Uint8Array(clean.length / 2);
	for (let i = 0; i < out.length; i++) {
		out[i] = parseInt(clean.slice(i * 2, i * 2 + 2), 16);
	}
	return out;
}

export function validateLayer(layer) {
	if (!layer || layer.format !== 'ic-layer-v1') {
		throw new Error('expected format ic-layer-v1');
	}
	if (layer.target && layer.target !== 'disc-image') {
		throw new Error(`unsupported target: ${layer.target} (expected disc-image)`);
	}
	if (!Array.isArray(layer.records)) {
		throw new Error('layer.records required');
	}
}

function yieldToUi() {
	return new Promise((resolve) => setTimeout(resolve, 0));
}

/**
 * Apply one layer to a disc image. Returns a new Uint8Array (may grow).
 * Yields periodically so the browser can paint on huge packs.
 *
 * opts.recordChunk — records between yields (default 4000)
 * opts.onProgress — optional (done, total) callback
 */
export async function applyLayer(imageBytes, layer, opts = {}) {
	validateLayer(layer);
	const recordChunk = opts.recordChunk ?? 4000;
	const onProgress = opts.onProgress;
	let size = imageBytes.length;
	const records = layer.records;
	const total = records.length;
	const parsed = new Array(total);

	for (let i = 0; i < total; i++) {
		const rec = records[i];
		const offset = Number(rec.offset);
		if (!Number.isFinite(offset) || offset < 0) {
			throw new Error(`bad offset: ${rec.offset}`);
		}
		const data = rec.hex != null ? parseHex(rec.hex) : new Uint8Array(rec.data || []);
		size = Math.max(size, offset + data.length);

const parsed = new Array(total);

