static s32 inflate_block(s32* e) {
    u32 t; /* block type */
    u32 b; /* bit buffer */
    u32 k; /* number of bits in bit buffer */

    /* make local bit buffer */
    b = bb;
    k = bk;

    /* read in last block bit */
    NEEDBITS(1);
    *e = (s32)b & 1;
    DUMPBITS(1);

    /* read in block type */
    NEEDBITS(2);
    t = (u32)b & 3;
    DUMPBITS(2);

    /* restore the global bit buffer */
    bb = b;
    bk = k;

    /* inflate that block type */
    if (t == 2) // Dynamic Huffman compressed block.
        return inflate_dynamic();
    if (t == 0) // A stored block, no compression.
        return inflate_stored();
    if (t == 1) // Static huffman compressed block.
        return inflate_fixed();

    /* bad block type */

/* inflate that block type */
    if (t == 2) // Dynamic Huffman compressed block.
        return inflate_dynamic();
    if (t == 0) // A stored block, no compression.
        return inflate_stored();
    if (t == 1) // Static huffman compressed block.
        return inflate_fixed();

    /* bad block type */
    return 2;
}

static s32 inflate() {
    s32 e; /* last block flag */
    s32 r; /* result code */

    /* initialize window, bit buffer */
    wp = 0;
    bk = 0;
    bb = 0;

    /* decompress until the last block */
    do {
        hufts = 0;
        if ((r = inflate_block(&e)) != 0)
            return r;
    } while (e == 0);

    /* Undo too much lookahead. The next read will be byte aligned so we
     * can discard unused bits in the last meaningful byte.
     */
    while (bk >= 8) {
        bk -= 8;
        inptr--;
    }

    return 0;
}

s32 Unzip(u8* src, u8* dst) {
    u8 buf[8];
